SELECT o.OrderID, o.OrderNo, u.UserName, p.PetName, o.OrderStatus, o.TotalAmount, o.CreateTime, o.prescription_id, pay.PayType as payType, pay.PayTime as payTime FROM pet_order o LEFT JOIN user u ON o.UserID = u.UserID LEFT JOIN pet p ON o.PetID = p.PetID LEFT JOIN payment_record pay ON o.OrderID = pay.OrderID WHERE 1=1
AND o.StoreID = #{storeId}
AND o.OrderStatus = #{orderStatus}
ORDER BY o.OrderID ASC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM pet_order o
WHERE 1=1

    AND o.StoreID = #{storeId}


    AND o.OrderStatus = #{orderStatus}
